-- Generated by scripts/build_compiled.py from src/fraudrules/rules/account-takeover/at-002-failed-logins-many-ips.yaml. Do not edit.
-- AT-002 Failed logins against one customer from many IP addresses
SELECT
  'AT-002' AS rule_id,
  'events' AS anchor_table,
  a.id AS anchor_id
FROM events AS a
JOIN events AS b
  ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 600
WHERE
  (
    a.event_type = 'login' AND a.outcome = 'failure'
  )
  AND (
    b.event_type = 'login' AND b.outcome = 'failure'
  )
GROUP BY
  a.id
HAVING
  COUNT(DISTINCT b.ip_token) >= 5;
